const pathFor = (file) => resolve(root, file);
const sha256 = (data) => createHash("sha256").update(data).digest("hex");
const readBuffer = (file) => readFile(pathFor(file));
const readText = (file) => readFile(pathFor(file), "utf8");
const writeText = (file, value) => writeFile(pathFor(file), value, "utf8");
const currentHash = async (file) => sha256(await readBuffer(file));

const packageJson = JSON.parse(await readText("package.json"));

if (packageJson.version === "4.6.21") {
  const mismatches = [];
  for (const [file, expected] of Object.entries(OUTPUT_HASHES)) {
    try { if (await currentHash(file) !== expected) mismatches.push(file); } catch { mismatches.push(file); }
  }
  if (mismatches.length) throw new Error(`4.6.21 ist gesetzt, aber Zieldateien weichen ab: ${mismatches.join(", ")}`);
  console.log("✓ 4.6.21 ist bereits vollständig installiert.");
  process.exit(0);
}

if (packageJson.version !== "4.6.20") {
  throw new Error(`Dieser Hotfix erwartet 4.6.20, gefunden wurde ${packageJson.version || "unbekannt"}.`);
}

const mismatches = [];
for (const [file, expected] of Object.entries(INPUT_HASHES)) {
  try {
    const actual = await currentHash(file);
    if (actual !== expected) mismatches.push(`${file}: Ausgangsdatei weicht vom geprüften 4.6.20-Stand ab`);
  } catch {
    mismatches.push(`${file}: konnte nicht gelesen werden`);
  }
}

const indexBefore = await readText("index.html");
const indexVersionCount = (indexBefore.match(/v4\.6\.20/g) || []).length;
if (indexVersionCount !== 1) mismatches.push(`index.html: erwartet genau einen sichtbaren v4.6.20-String, gefunden ${indexVersionCount}`);

if (mismatches.length) {
  throw new Error(`Sicherheitsstopp vor der ersten Änderung:\n- ${mismatches.join("\n- ")}`);
}

for (const [file, encoded] of Object.entries(OUTPUTS)) {
  await writeFile(pathFor(file), Buffer.from(encoded, "base64"));
  console.log(`✓ ${file}`);
}

try { await unlink(pathFor("tests/ui-4620.test.mjs")); console.log("✓ tests/ui-4620.test.mjs entfernt"); } catch (error) { if (error?.code !== "ENOENT") throw error; }

await writeText("index.html", indexBefore.replace("v4.6.20", "v4.6.21"));
console.log("✓ index.html: sichtbare Version auf 4.6.21");

let changelog = await readText("CHANGELOG.md");
const changelogEntry = `## 4.6.21 – Mobile Density Hotfix\n\n- iPhone-Header nutzt die obere Safe Area enger und blendet die Eyebrow auf Smartphones aus.\n- Logo und Theme-Aktion werden kompakter, ohne die Statusleiste zu überlagern.\n- Bottom-Navigation überschreibt die alte direkte Span-Schriftgröße und wird dadurch tatsächlich flacher.\n- Primäre Hinzufügen-Aktion und Icons werden auf native Tab-Bar-Dichte reduziert.\n- Safari-sichere Share-Card-Breitenbegrenzung bleibt erhalten.\n\n`;
if (!changelog.includes("## 4.6.21 – Mobile Density Hotfix")) {
  const firstRelease = changelog.indexOf("## ");
  changelog = firstRelease >= 0 ? `${changelog.slice(0, firstRelease)}${changelogEntry}${changelog.slice(firstRelease)}` : `${changelog.trimEnd()}\n\n${changelogEntry}`;
  await writeText("CHANGELOG.md", changelog);
  console.log("✓ CHANGELOG.md ergänzt");
}

await writeText("QUALITY-4.6.21-HOTFIX.md", `# Entenarchiv 4.6.21 Mobile Density Hotfix\n\n## Ursache\n\n4.6.20 reduzierte zwar Container-Mindesthöhen, zwei Effekte hielten die mobile Oberfläche optisch groß: die volle iOS-Safe-Area plus Zusatzabstand im Header und eine alte direkte Regel \`.bottom-nav span { font-size: 1.15rem }\`, die die kleineren Item-Schriftgrößen überstimmte.\n\n## Änderung\n\n- Smartphone-Header nutzt die Safe Area um 14 px enger, behält aber einen Mindestabstand.\n- Eyebrow wird bis 600 px ausgeblendet; Logo 36 px, Theme-Aktion 38 px.\n- Bottom-Nav-Texte erhalten explizit 0.68 rem statt der historischen 1.15 rem.\n- Navigationseinträge 42 px, primäre Aktion 46 px, Icons 19/22 px.\n- Untere Safe Area wird weiterhin berücksichtigt, aber um 8 px enger genutzt.\n- Share-Card-Breitenfix aus 4.6.20 bleibt bestehen.\n\n## Sicherheit\n\nKeine Änderungen an IndexedDB, Data Stack, Featurelogik oder Sammlungsdaten. Neue Regressionstests sichern die direkten Span-Regeln und die mobile Safe-Area-Dichte.\n`);
console.log("✓ QUALITY-4.6.21-HOTFIX.md");

const verify = [];
for (const [file, expected] of Object.entries(OUTPUT_HASHES)) {
  try { if (await currentHash(file) !== expected) verify.push(file); } catch { verify.push(file); }
}
if (verify.length) throw new Error(`Zielprüfung fehlgeschlagen: ${verify.join(", ")}`);

const finalIndex = await readText("index.html");
if ((finalIndex.match(/v4\.6\.21/g) || []).length !== 1) throw new Error("index.html enthält nicht genau einen sichtbaren v4.6.21-String.");

console.log("✓ Entenarchiv 4.6.21 Mobile Density Hotfix vollständig angewendet.");
